const ps = await fetch('/api/policies', {headers:{Accept:'application/json'}}).then(r=>r.json());
const summary = ps.map(p => ({
  policyId: p.latestVersion && p.latestVersion.policyId,
  versionId: p.latestVersion && p.latestVersion.id,
  title: p.title || p.name,
  type: p.type || p.policyType,
  defaultAction: p.latestVersion && p.latestVersion.defaultAction,
  ruleTypes: Array.from(new Set((p.rules||[]).map(r => r.type))),
  ruleCount: (p.rules||[]).length
}));
const hits = [];
ps.forEach(p => (p.rules||[]).forEach(r => {
  const s = JSON.stringify(r);
  if (/aiofile/i.test(s)) hits.push({ policyId: p.latestVersion && p.latestVersion.policyId, title: p.title || p.name, rule: r });
}));
({ policies: summary, aiofileRules: hits });

// modal should still be open; drive the react-select via keyboard
const inp = Array.from(document.querySelectorAll('input[type=text]')).find(i => {
  const c = i.closest('[class*=select__control],[class*=Select__control]');
  return c || /Select one or more/.test((i.parentElement&&i.parentElement.parentElement&&i.parentElement.parentElement.innerText)||'');
});
if (!inp) { ({error:'no select input found', open: !!document.querySelector('[class*=modal]')}); } else {
inp.focus();
inp.dispatchEvent(new KeyboardEvent('keydown', {key:'ArrowDown', code:'ArrowDown', keyCode:40, which:40, bubbles:true}));
await new Promise(r=>setTimeout(r,800));
const opts = Array.from(document.querySelectorAll('[class*=select__option],[class*=Select__option],[role=option]')).map(o=>(o.innerText||'').trim());
inp.dispatchEvent(new KeyboardEvent('keydown', {key:'Enter', code:'Enter', keyCode:13, which:13, bubbles:true}));
await new Promise(r=>setTimeout(r,800));
({ optionsSeen: opts, controlNow: (document.querySelector('[class*=select__control],[class*=Select__control]')||{}).innerText });
}

